-- Additive local-development storage. Apply explicitly to the local D1 database.
CREATE TABLE IF NOT EXISTS rer_mail_development_outbox (
  sequence INTEGER PRIMARY KEY AUTOINCREMENT,
  id TEXT NOT NULL UNIQUE,
  created_at INTEGER NOT NULL,
  message TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS rer_mail_development_outbox_order
  ON rer_mail_development_outbox(created_at DESC, sequence DESC);

CREATE TABLE rer_portability_state (
  id INTEGER PRIMARY KEY CHECK(id=1), source_identity TEXT NOT NULL, epoch INTEGER NOT NULL DEFAULT 0,
  import_job TEXT, applying INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE rer_portability_jobs (
  id TEXT PRIMARY KEY, kind TEXT NOT NULL, actor TEXT NOT NULL, phase TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0, metadata TEXT NOT NULL
);
CREATE TABLE rer_portability_parts (
  job TEXT NOT NULL REFERENCES rer_portability_jobs(id) ON DELETE CASCADE,
  idx INTEGER NOT NULL, sha256 TEXT NOT NULL, PRIMARY KEY(job,idx)
);
CREATE TABLE rer_portability_segments (
  job TEXT NOT NULL REFERENCES rer_portability_jobs(id) ON DELETE CASCADE,
  part INTEGER NOT NULL, segment INTEGER NOT NULL, data TEXT NOT NULL, PRIMARY KEY(job,part,segment)
);
CREATE TABLE rer_portability_owned (
  job TEXT NOT NULL REFERENCES rer_portability_jobs(id) ON DELETE CASCADE,
  bucket TEXT NOT NULL, key TEXT NOT NULL, PRIMARY KEY(job,bucket,key)
);
CREATE TABLE rer_portability_journal (
  source TEXT NOT NULL, tombstone TEXT NOT NULL, PRIMARY KEY(source,tombstone)
);
CREATE TABLE rer_portability_epochs (source TEXT PRIMARY KEY, epoch INTEGER NOT NULL);
CREATE TABLE rer_portability_guard (value INTEGER NOT NULL CHECK(value=1));

-- Local dev identity for an existing store. Apply as a NEW numbered migration
-- under the seed's next unused number; never rewrite an applied migration.
-- SQLite cannot change a CHECK in place, so oa_sessions is rebuilt with 'dev'
-- admitted, keeping every row, column, index and constraint. No table refers
-- to oa_sessions. The file is also safe on a store created from the current
-- schema/operator-auth.sql, so a fresh store may apply both.
CREATE TABLE oa_sessions_dev_rebuild (
 id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE,
 operator_id TEXT NOT NULL REFERENCES oa_operators(id), operator_version INTEGER NOT NULL,
 kind TEXT NOT NULL CHECK(kind IN ('native','review','oidc','password','dev')),
 source_token_id TEXT UNIQUE REFERENCES oa_tokens(id),
 created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, revoked_at INTEGER
);
INSERT INTO oa_sessions_dev_rebuild(id,token_hash,operator_id,operator_version,kind,source_token_id,created_at,expires_at,revoked_at)
 SELECT id,token_hash,operator_id,operator_version,kind,source_token_id,created_at,expires_at,revoked_at FROM oa_sessions;
DROP TABLE oa_sessions;
ALTER TABLE oa_sessions_dev_rebuild RENAME TO oa_sessions;
CREATE INDEX oa_sessions_operator ON oa_sessions(operator_id);
CREATE TABLE IF NOT EXISTS oa_dev_credentials (
 credential TEXT NOT NULL, id TEXT NOT NULL, created_at INTEGER NOT NULL,
 PRIMARY KEY(credential, id)
);

-- Initial Evidence domain. Facts append from here; no prior business records.
CREATE TABLE controls (id TEXT PRIMARY KEY, name TEXT NOT NULL, group_name TEXT NOT NULL CHECK(group_name IN ('Access','Data','Change','People','Vendors')), created_at TEXT NOT NULL);
CREATE TABLE requirements (id TEXT PRIMARY KEY, control_id TEXT NOT NULL REFERENCES controls(id), name TEXT NOT NULL, cadence TEXT NOT NULL CHECK(cadence IN ('daily','weekly','monthly','quarterly')), created_at TEXT NOT NULL);
CREATE TABLE exhibits (id TEXT PRIMARY KEY, object_key TEXT NOT NULL UNIQUE, filename TEXT NOT NULL, size INTEGER NOT NULL, media_type TEXT NOT NULL);
CREATE TABLE receipts (id TEXT PRIMARY KEY, requirement_id TEXT NOT NULL REFERENCES requirements(id), exhibit_id TEXT NOT NULL UNIQUE REFERENCES exhibits(id), origin TEXT NOT NULL CHECK(origin IN ('source-observed','manually-asserted','imported')), source TEXT NOT NULL, covered_from TEXT NOT NULL, covered_to TEXT NOT NULL, added_by TEXT NOT NULL REFERENCES oa_operators(id), added_by_name TEXT NOT NULL, added_at TEXT NOT NULL, sha256 TEXT NOT NULL, supersedes TEXT UNIQUE REFERENCES receipts(id), CHECK(covered_from <= covered_to));
CREATE INDEX receipts_requirement ON receipts(requirement_id);
CREATE TRIGGER receipts_no_update BEFORE UPDATE ON receipts BEGIN SELECT RAISE(ABORT, 'immutable_receipt'); END;
CREATE TRIGGER receipts_no_delete BEFORE DELETE ON receipts BEGIN SELECT RAISE(ABORT, 'immutable_receipt'); END;
CREATE TRIGGER exhibits_no_update BEFORE UPDATE ON exhibits BEGIN SELECT RAISE(ABORT, 'immutable_exhibit'); END;
CREATE TRIGGER exhibits_no_delete BEFORE DELETE ON exhibits BEGIN SELECT RAISE(ABORT, 'immutable_exhibit'); END;

-- Receipt attribution is provenance, never an authentication grant. Move the
-- immutable facts without changing one value; future uploads copy native identity.
CREATE TABLE receipt_actors (id TEXT PRIMARY KEY, display_name TEXT NOT NULL);
INSERT INTO receipt_actors SELECT DISTINCT o.id,o.display_name FROM oa_operators o JOIN receipts r ON r.added_by=o.id;
DROP TRIGGER receipts_no_update;
DROP TRIGGER receipts_no_delete;
CREATE TABLE custody_receipts (id TEXT PRIMARY KEY, requirement_id TEXT NOT NULL REFERENCES requirements(id), exhibit_id TEXT NOT NULL UNIQUE REFERENCES exhibits(id), origin TEXT NOT NULL CHECK(origin IN ('source-observed','manually-asserted','imported')), source TEXT NOT NULL, covered_from TEXT NOT NULL, covered_to TEXT NOT NULL, added_by TEXT NOT NULL REFERENCES receipt_actors(id), added_by_name TEXT NOT NULL, added_at TEXT NOT NULL, sha256 TEXT NOT NULL, supersedes TEXT UNIQUE REFERENCES custody_receipts(id), CHECK(covered_from <= covered_to));
INSERT INTO custody_receipts SELECT * FROM receipts;
DROP TABLE receipts;
ALTER TABLE custody_receipts RENAME TO receipts;
CREATE INDEX receipts_requirement ON receipts(requirement_id);
CREATE TRIGGER receipts_no_update BEFORE UPDATE ON receipts BEGIN SELECT RAISE(ABORT, 'immutable_receipt'); END;
CREATE TRIGGER receipts_no_delete BEFORE DELETE ON receipts BEGIN SELECT RAISE(ABORT, 'immutable_receipt'); END;
CREATE TRIGGER receipts_native_actor BEFORE INSERT ON receipts BEGIN INSERT OR IGNORE INTO receipt_actors SELECT id,display_name FROM oa_operators WHERE id=NEW.added_by; END;
-- Used only inside the restore transaction; zero is impossible by construction.
CREATE TABLE custody_admission (singleton INTEGER PRIMARY KEY CHECK(singleton=1), empty_check INTEGER NOT NULL CHECK(empty_check=1));

