CREATE TRIGGER IF NOT EXISTS ik_d1_custody_state_ik_d1_stream_pages_delete AFTER DELETE ON ik_d1_stream_pages BEGIN UPDATE ik_d1_custody_states SET revision=revision+1 WHERE job_id=OLD.job_id; END;
CREATE TRIGGER IF NOT EXISTS ik_d1_custody_state_stream_update BEFORE UPDATE ON ik_d1_streams BEGIN UPDATE ik_d1_custody_states SET revision=revision+1 WHERE job_id IN (SELECT job_id FROM ik_d1_stream_pages WHERE stream_id=OLD.id); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_custody_state_stream_delete BEFORE DELETE ON ik_d1_streams BEGIN UPDATE ik_d1_custody_states SET revision=revision+1 WHERE job_id IN (SELECT job_id FROM ik_d1_stream_pages WHERE stream_id=OLD.id); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_custody_state_ik_d1_erased_sources_insert AFTER INSERT ON ik_d1_erased_sources BEGIN UPDATE ik_d1_custody_states SET revision=revision+1 WHERE job_id IN (SELECT i.job_id FROM ik_d1_plan_index i JOIN ik_jobs j ON j.id=i.job_id WHERE i.source_identity=NEW.identity AND j.destination=NEW.destination); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_custody_state_ik_d1_erased_sources_update AFTER UPDATE ON ik_d1_erased_sources BEGIN UPDATE ik_d1_custody_states SET revision=revision+1 WHERE job_id IN (SELECT i.job_id FROM ik_d1_plan_index i JOIN ik_jobs j ON j.id=i.job_id WHERE (i.source_identity=OLD.identity AND j.destination=OLD.destination) OR (i.source_identity=NEW.identity AND j.destination=NEW.destination)); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_custody_state_ik_d1_erased_sources_delete AFTER DELETE ON ik_d1_erased_sources BEGIN UPDATE ik_d1_custody_states SET revision=revision+1 WHERE job_id IN (SELECT i.job_id FROM ik_d1_plan_index i JOIN ik_jobs j ON j.id=i.job_id WHERE i.source_identity=OLD.identity AND j.destination=OLD.destination); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_custody_state_ik_d1_erased_targets_insert AFTER INSERT ON ik_d1_erased_targets BEGIN UPDATE ik_d1_custody_states SET revision=revision+1 WHERE job_id IN (SELECT i.job_id FROM ik_d1_plan_index i JOIN ik_jobs j ON j.id=i.job_id WHERE i.target_identity=NEW.identity AND j.destination=NEW.destination); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_custody_state_ik_d1_erased_targets_update AFTER UPDATE ON ik_d1_erased_targets BEGIN UPDATE ik_d1_custody_states SET revision=revision+1 WHERE job_id IN (SELECT i.job_id FROM ik_d1_plan_index i JOIN ik_jobs j ON j.id=i.job_id WHERE (i.target_identity=OLD.identity AND j.destination=OLD.destination) OR (i.target_identity=NEW.identity AND j.destination=NEW.destination)); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_custody_state_ik_d1_erased_targets_delete AFTER DELETE ON ik_d1_erased_targets BEGIN UPDATE ik_d1_custody_states SET revision=revision+1 WHERE job_id IN (SELECT i.job_id FROM ik_d1_plan_index i JOIN ik_jobs j ON j.id=i.job_id WHERE i.target_identity=OLD.identity AND j.destination=OLD.destination); END;
CREATE TABLE IF NOT EXISTS ik_d1_reversal_fences (job_id TEXT PRIMARY KEY REFERENCES ik_jobs(id) ON DELETE CASCADE,action TEXT NOT NULL,fence INTEGER NOT NULL,state_revision INTEGER NOT NULL,erased_records INTEGER NOT NULL,reused INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS ik_provenance_job ON ik_provenance(job_id,reversed,ordinal,effect_ordinal);
CREATE INDEX IF NOT EXISTS ik_provenance_source ON ik_provenance(source_identity,reversed);
CREATE INDEX IF NOT EXISTS ik_d1_history_source ON ik_d1_history(source_identity);
CREATE INDEX IF NOT EXISTS ik_sources_job ON ik_sources(job_id);
CREATE TABLE IF NOT EXISTS ik_d1_preparation_receipts (stage_id TEXT PRIMARY KEY REFERENCES ik_d1_staging(id) ON DELETE CASCADE, generation TEXT NOT NULL, codec_id TEXT, header_hash TEXT NOT NULL, header_size INTEGER NOT NULL, header_chunks INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ik_d1_staging_headers (stage_id TEXT NOT NULL REFERENCES ik_d1_staging(id) ON DELETE CASCADE, ordinal INTEGER NOT NULL, body TEXT NOT NULL, body_hash TEXT NOT NULL, body_size INTEGER NOT NULL, PRIMARY KEY(stage_id,ordinal));
CREATE TRIGGER IF NOT EXISTS ik_d1_preparation_receipts_insert AFTER INSERT ON ik_d1_preparation_receipts BEGIN UPDATE ik_d1_staging SET revision=revision+1,sealed_revision=NULL WHERE id=NEW.stage_id; END;
CREATE TRIGGER IF NOT EXISTS ik_d1_staging_headers_insert AFTER INSERT ON ik_d1_staging_headers BEGIN UPDATE ik_d1_staging SET revision=revision+1,sealed_revision=NULL WHERE id=NEW.stage_id; END;
CREATE TRIGGER IF NOT EXISTS ik_d1_preparation_receipts_update AFTER UPDATE ON ik_d1_preparation_receipts BEGIN UPDATE ik_d1_staging SET revision=revision+1,sealed_revision=NULL WHERE id=OLD.stage_id OR id=NEW.stage_id; END;
CREATE TRIGGER IF NOT EXISTS ik_d1_staging_headers_update AFTER UPDATE ON ik_d1_staging_headers BEGIN UPDATE ik_d1_staging SET revision=revision+1,sealed_revision=NULL WHERE id=OLD.stage_id OR id=NEW.stage_id; END;
CREATE TRIGGER IF NOT EXISTS ik_d1_preparation_receipts_delete AFTER DELETE ON ik_d1_preparation_receipts BEGIN UPDATE ik_d1_staging SET revision=revision+1,sealed_revision=NULL WHERE id=OLD.stage_id; END;
CREATE TRIGGER IF NOT EXISTS ik_d1_staging_headers_delete AFTER DELETE ON ik_d1_staging_headers BEGIN UPDATE ik_d1_staging SET revision=revision+1,sealed_revision=NULL WHERE id=OLD.stage_id; END;
CREATE TRIGGER IF NOT EXISTS ik_d1_preparation_receipt_immutable BEFORE UPDATE ON ik_d1_preparation_receipts BEGIN SELECT RAISE(ABORT,'IMPORT_PREPARATION_CHANGED'); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_staging_headers_registered BEFORE INSERT ON ik_d1_staging_headers WHEN NOT EXISTS(SELECT 1 FROM ik_d1_staging WHERE id=NEW.stage_id AND registered_revision IS NOT NULL) BEGIN SELECT RAISE(ABORT,'IMPORT_STAGE_INDEX_REQUIRED'); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_preparation_privacy_insert AFTER INSERT ON ik_d1_staging_index BEGIN DELETE FROM ik_d1_staging_headers WHERE stage_id=NEW.stage_id; END;
CREATE TRIGGER IF NOT EXISTS ik_d1_preparation_privacy_update AFTER UPDATE ON ik_d1_staging_index BEGIN DELETE FROM ik_d1_staging_headers WHERE stage_id=OLD.stage_id OR stage_id=NEW.stage_id; END;
CREATE TRIGGER IF NOT EXISTS ik_d1_preparation_privacy_delete AFTER DELETE ON ik_d1_staging_index BEGIN DELETE FROM ik_d1_staging_headers WHERE stage_id=OLD.stage_id; END;
CREATE TABLE IF NOT EXISTS ik_d1_retirements (id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('job','stream')), destination TEXT NOT NULL, receipt_id TEXT NOT NULL, retired_at TEXT NOT NULL, PRIMARY KEY(id, kind));
CREATE TABLE IF NOT EXISTS ik_d1_erasure_journal (id TEXT PRIMARY KEY, destination TEXT NOT NULL, recorded_at TEXT NOT NULL, records_erased INTEGER NOT NULL CHECK(records_erased>=0), jobs_retired INTEGER NOT NULL CHECK(jobs_retired>=0), streams_retired INTEGER NOT NULL CHECK(streams_retired>=0), stores_json TEXT NOT NULL CHECK(json_valid(stores_json)));
CREATE INDEX IF NOT EXISTS ik_d1_erasure_journal_time ON ik_d1_erasure_journal(destination, recorded_at);
CREATE TRIGGER IF NOT EXISTS ik_d1_erasure_journal_insert BEFORE INSERT ON ik_d1_erasure_journal WHEN EXISTS(SELECT 1 FROM ik_d1_erasure_journal WHERE id=NEW.id) BEGIN SELECT RAISE(ABORT,'IMPORT_ERASURE_JOURNAL_APPEND_ONLY'); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_retirement_insert BEFORE INSERT ON ik_d1_retirements WHEN EXISTS(SELECT 1 FROM ik_d1_retirements WHERE id=NEW.id AND kind=NEW.kind) BEGIN SELECT RAISE(ABORT,'IMPORT_RETIREMENT_CHANGED'); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_erasure_journal_update BEFORE UPDATE ON ik_d1_erasure_journal BEGIN SELECT RAISE(ABORT,'IMPORT_ERASURE_JOURNAL_APPEND_ONLY'); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_erasure_journal_delete BEFORE DELETE ON ik_d1_erasure_journal BEGIN SELECT RAISE(ABORT,'IMPORT_ERASURE_JOURNAL_APPEND_ONLY'); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_retirement_update BEFORE UPDATE ON ik_d1_retirements BEGIN SELECT RAISE(ABORT,'IMPORT_RETIREMENT_CHANGED'); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_retirement_delete BEFORE DELETE ON ik_d1_retirements BEGIN SELECT RAISE(ABORT,'IMPORT_RETIREMENT_CHANGED'); END;
CREATE TABLE IF NOT EXISTS ik_d1_erasure_tally (receipt_id TEXT NOT NULL, store TEXT NOT NULL, image TEXT NOT NULL);
DROP TRIGGER IF EXISTS ik_d1_stream_revision_update;
CREATE TRIGGER ik_d1_stream_revision_update BEFORE UPDATE ON ik_d1_stream_revisions WHEN NEW.stream_id IS NOT OLD.stream_id OR NEW.destination IS NOT OLD.destination OR NEW.mapping_version IS NOT OLD.mapping_version OR NEW.principal_id IS NOT OLD.principal_id OR NEW.fingerprint IS NOT OLD.fingerprint OR NEW.total IS NOT OLD.total OR NEW.layout_hash IS NOT OLD.layout_hash OR NEW.layout_revision<OLD.layout_revision OR NEW.progress_revision<=OLD.progress_revision OR ((NEW.namespace IS NOT OLD.namespace OR NEW.operation_key IS NOT OLD.operation_key) AND NOT (NEW.namespace='' AND NEW.operation_key='' AND NOT EXISTS(SELECT 1 FROM ik_d1_streams WHERE id=OLD.stream_id) AND EXISTS(SELECT 1 FROM ik_d1_retirements WHERE id=OLD.stream_id AND kind='stream'))) BEGIN SELECT RAISE(ABORT,'IMPORT_STREAM_REVISION_CHANGED'); END;
-- A preview is a retained, inert source. Only a later explicit approval creates a job.
CREATE TABLE import_reviews (id TEXT PRIMARY KEY, actor_id TEXT NOT NULL, actor_name TEXT NOT NULL, staged_at TEXT NOT NULL, object_key TEXT NOT NULL UNIQUE, archive_sha256 TEXT NOT NULL, archive_size INTEGER NOT NULL, summary_json TEXT NOT NULL, mapping_json TEXT, fingerprint TEXT, job_id TEXT REFERENCES ik_jobs(id), approved_at TEXT);
CREATE TABLE import_additions (kind TEXT NOT NULL, id TEXT NOT NULL, review_id TEXT NOT NULL REFERENCES import_reviews(id), value_json TEXT NOT NULL, PRIMARY KEY(kind,id));
CREATE TABLE import_active (kind TEXT NOT NULL, id TEXT NOT NULL, revision TEXT NOT NULL, value_json TEXT NOT NULL, PRIMARY KEY(kind,id), FOREIGN KEY(kind,id) REFERENCES import_additions(kind,id));
CREATE TRIGGER import_additions_no_update BEFORE UPDATE ON import_additions BEGIN SELECT RAISE(ABORT,'immutable_import_addition'); END;
CREATE TRIGGER import_additions_no_delete BEFORE DELETE ON import_additions BEGIN SELECT RAISE(ABORT,'immutable_import_addition'); END;
CREATE TRIGGER import_review_source_immutable BEFORE UPDATE ON import_reviews WHEN NEW.id IS NOT OLD.id OR NEW.actor_id IS NOT OLD.actor_id OR NEW.actor_name IS NOT OLD.actor_name OR NEW.staged_at IS NOT OLD.staged_at OR NEW.object_key IS NOT OLD.object_key OR NEW.archive_sha256 IS NOT OLD.archive_sha256 OR NEW.archive_size IS NOT OLD.archive_size OR NEW.summary_json IS NOT OLD.summary_json OR (OLD.approved_at IS NOT NULL AND (NEW.approved_at IS NOT OLD.approved_at OR NEW.mapping_json IS NOT OLD.mapping_json OR NEW.fingerprint IS NOT OLD.fingerprint OR (OLD.job_id IS NOT NULL AND NEW.job_id IS NOT OLD.job_id))) BEGIN SELECT RAISE(ABORT,'immutable_import_review'); END;
CREATE TRIGGER import_reviews_no_delete BEFORE DELETE ON import_reviews BEGIN SELECT RAISE(ABORT,'immutable_import_review'); END;

-- Capability grants retain only digests. NULL digests are inert archive records.
CREATE TABLE agent_tokens (
 id TEXT PRIMARY KEY, label TEXT NOT NULL, token_hash TEXT UNIQUE,
 created_by TEXT NOT NULL, created_by_name TEXT NOT NULL, created_at TEXT NOT NULL,
 expires_at TEXT NOT NULL, revoked_at TEXT, revoked_by TEXT,
 CHECK ((revoked_at IS NULL) = (revoked_by IS NULL)),
 CHECK (token_hash IS NULL OR (length(token_hash)=64 AND token_hash NOT GLOB '*[^a-f0-9]*'))
);
CREATE TABLE agent_proposals (
 id TEXT PRIMARY KEY, token_id TEXT NOT NULL REFERENCES agent_tokens(id),
 created_at TEXT NOT NULL, input_json TEXT NOT NULL, snapshot_json TEXT NOT NULL,
 snapshot_hash TEXT NOT NULL CHECK(length(snapshot_hash)=64 AND snapshot_hash NOT GLOB '*[^a-f0-9]*')
);
CREATE TABLE agent_decisions (
 id TEXT PRIMARY KEY, proposal_id TEXT NOT NULL UNIQUE REFERENCES agent_proposals(id),
 action TEXT NOT NULL CHECK(action IN ('approved','rejected')),
 actor_id TEXT NOT NULL, actor_name TEXT NOT NULL, decided_at TEXT NOT NULL,
 snapshot_hash TEXT NOT NULL, folder_id TEXT UNIQUE REFERENCES review_folders(id),
 CHECK ((action='approved' AND folder_id IS NOT NULL) OR (action='rejected' AND folder_id IS NULL))
);
CREATE TRIGGER immutable_agent_token BEFORE UPDATE ON agent_tokens
 WHEN NEW.id IS NOT OLD.id OR NEW.label IS NOT OLD.label OR NEW.token_hash IS NOT OLD.token_hash
 OR NEW.created_by IS NOT OLD.created_by OR NEW.created_by_name IS NOT OLD.created_by_name
 OR NEW.created_at IS NOT OLD.created_at OR NEW.expires_at IS NOT OLD.expires_at
 OR OLD.revoked_at IS NOT NULL OR NEW.revoked_at IS NULL OR NEW.revoked_by IS NULL
 BEGIN SELECT RAISE(ABORT,'immutable_agent_token'); END;
CREATE TRIGGER retained_agent_token BEFORE DELETE ON agent_tokens BEGIN SELECT RAISE(ABORT,'retained_agent_token'); END;
CREATE TRIGGER immutable_agent_proposal BEFORE UPDATE ON agent_proposals BEGIN SELECT RAISE(ABORT,'immutable_agent_proposal'); END;
CREATE TRIGGER retained_agent_proposal BEFORE DELETE ON agent_proposals BEGIN SELECT RAISE(ABORT,'retained_agent_proposal'); END;
CREATE TRIGGER exact_agent_decision BEFORE INSERT ON agent_decisions
 WHEN NEW.snapshot_hash IS NOT (SELECT snapshot_hash FROM agent_proposals WHERE id=NEW.proposal_id)
 BEGIN SELECT RAISE(ABORT,'exact_agent_decision'); END;
CREATE TRIGGER immutable_agent_decision BEFORE UPDATE ON agent_decisions BEGIN SELECT RAISE(ABORT,'immutable_agent_decision'); END;
CREATE TRIGGER retained_agent_decision BEFORE DELETE ON agent_decisions BEGIN SELECT RAISE(ABORT,'retained_agent_decision'); END;

-- Additive provider controls. An absent setting means off, including upgrades.
CREATE TABLE IF NOT EXISTS oa_auth_settings (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1), idp_sign_in INTEGER NOT NULL CHECK(idp_sign_in IN (0,1)), generation INTEGER NOT NULL DEFAULT 0, first_setup INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS oa_auth_audit (
 id TEXT PRIMARY KEY, actor_id TEXT NOT NULL, action TEXT NOT NULL, value TEXT NOT NULL, created_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS oa_provider_sessions (
 session_id TEXT PRIMARY KEY, issuer TEXT NOT NULL, subject TEXT NOT NULL, sid TEXT, generation INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS oa_provider_session_identity ON oa_provider_sessions(issuer,subject,sid);
CREATE TABLE IF NOT EXISTS oa_logout_events (
 issuer TEXT NOT NULL, jti TEXT NOT NULL, consumed_at INTEGER NOT NULL CHECK(consumed_at>=0), PRIMARY KEY(issuer,jti)
);

CREATE TRIGGER IF NOT EXISTS oa_first_setup_provider_setting AFTER INSERT ON oa_bootstrap BEGIN
 INSERT INTO oa_auth_settings(singleton,idp_sign_in,generation,first_setup) VALUES(1,0,0,1) ON CONFLICT DO NOTHING;
END;

CREATE TABLE IF NOT EXISTS oa_credentials (
 id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE, operator_id TEXT NOT NULL REFERENCES oa_operators(id),
 operator_version INTEGER, kind TEXT NOT NULL, expires_at INTEGER NOT NULL, revoked_at INTEGER
);

-- Session provenance for OIDC pins. Apply as a new migration on existing stores.
-- External admission has no OIDC pin and does not require OIDC protocol tables.
CREATE TABLE IF NOT EXISTS oa_provider_session_pins (
 session_id TEXT PRIMARY KEY, provider_id TEXT NOT NULL, issuer TEXT NOT NULL,
 client_id TEXT NOT NULL, linked_at INTEGER NOT NULL
);

-- Ephemeral app-local setup attempts are never exported. A native claim binds
-- only attempts opened before that claim to its exact owner/session authority,
-- in its own bootstrap transaction.
CREATE TABLE IF NOT EXISTS oa_setup_links (
 interface TEXT PRIMARY KEY, attempt_id TEXT NOT NULL, expires_at INTEGER NOT NULL,
 owner_id TEXT, owner_version INTEGER, session_id TEXT,
 completed INTEGER NOT NULL DEFAULT 0 CHECK(completed IN (0,1))
);
CREATE TRIGGER IF NOT EXISTS oa_native_claim_closes_provider_setup AFTER INSERT ON oa_sessions
WHEN NEW.kind='native' AND NOT EXISTS(SELECT 1 FROM oa_sessions WHERE operator_id=NEW.operator_id AND id!=NEW.id) AND EXISTS(SELECT 1 FROM oa_bootstrap WHERE claim_id=NEW.operator_id AND claimed_at=NEW.created_at)
BEGIN
 UPDATE oa_auth_settings SET first_setup=0 WHERE singleton=1 AND NOT EXISTS(
  SELECT 1 FROM oa_setup_links WHERE interface='oidc-provider@1' AND completed=0 AND owner_id IS NULL AND expires_at>NEW.created_at
 );
 UPDATE oa_setup_links SET owner_id=NEW.operator_id,owner_version=NEW.operator_version,session_id=NEW.id
 WHERE owner_id IS NULL AND completed=0 AND expires_at>NEW.created_at;
END;

-- Program domain. Widen control groups and requirement cadences in place: the
-- same rows and ids return before commit, so receipt references stay intact.
PRAGMA defer_foreign_keys = on;
CREATE TABLE controls_stash AS SELECT * FROM controls;
CREATE TABLE requirements_stash AS SELECT * FROM requirements;
DROP TABLE requirements;
DROP TABLE controls;
CREATE TABLE controls (id TEXT PRIMARY KEY, name TEXT NOT NULL, group_name TEXT NOT NULL CHECK(group_name IN ('Access','Data','Change','People','Vendors','Operations','Governance')), created_at TEXT NOT NULL);
CREATE TABLE requirements (id TEXT PRIMARY KEY, control_id TEXT NOT NULL REFERENCES controls(id), name TEXT NOT NULL, cadence TEXT NOT NULL CHECK(cadence IN ('daily','weekly','monthly','quarterly','semi-annual','annual')), created_at TEXT NOT NULL);
INSERT INTO controls SELECT * FROM controls_stash;
INSERT INTO requirements SELECT * FROM requirements_stash;
DROP TABLE requirements_stash;
DROP TABLE controls_stash;
CREATE INDEX requirements_control ON requirements(control_id);

-- People named as owners, contributors, approvers and reminder recipients.
CREATE TABLE people (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE COLLATE NOCASE, kind TEXT NOT NULL CHECK(kind IN ('employee','contractor','auditor','other')), created_at TEXT NOT NULL, created_by TEXT NOT NULL);

-- Permanent product action audit: actor, subject, outcome; never raw secrets.
CREATE TABLE product_audit (id TEXT PRIMARY KEY, actor_kind TEXT NOT NULL CHECK(actor_kind IN ('owner','token','system')), actor_id TEXT NOT NULL, actor_name TEXT NOT NULL, action TEXT NOT NULL, subject TEXT NOT NULL, outcome TEXT NOT NULL CHECK(outcome IN ('succeeded','refused','failed','uncertain')), detail TEXT NOT NULL DEFAULT '', at TEXT NOT NULL);
CREATE INDEX product_audit_at ON product_audit(at);
CREATE TRIGGER product_audit_no_update BEFORE UPDATE ON product_audit BEGIN SELECT RAISE(ABORT,'immutable_audit'); END;
CREATE TRIGGER product_audit_no_delete BEFORE DELETE ON product_audit BEGIN SELECT RAISE(ABORT,'immutable_audit'); END;

-- Framework programs (PROGRAM-001). Scope fields are current values; every
-- change appends a full revision snapshot with actor and reason.
CREATE TABLE programs (
 id TEXT PRIMARY KEY, framework TEXT NOT NULL CHECK(framework IN ('soc2','iso27001','hipaa','pci')), edition TEXT NOT NULL,
 name TEXT NOT NULL, legal_entity TEXT NOT NULL, report_type TEXT, categories TEXT NOT NULL DEFAULT '[]',
 products TEXT NOT NULL DEFAULT '[]', teams TEXT NOT NULL DEFAULT '[]', regions TEXT NOT NULL DEFAULT '[]', systems TEXT NOT NULL DEFAULT '[]',
 audit_from TEXT NOT NULL, audit_to TEXT NOT NULL, assessor TEXT NOT NULL DEFAULT '', lead_person_id TEXT REFERENCES people(id),
 milestones TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK(audit_from <= audit_to)
);
CREATE TABLE program_revisions (id TEXT PRIMARY KEY, program_id TEXT NOT NULL REFERENCES programs(id), revision INTEGER NOT NULL, snapshot_json TEXT NOT NULL, actor_id TEXT NOT NULL, actor_name TEXT NOT NULL, reason TEXT NOT NULL, at TEXT NOT NULL, UNIQUE(program_id,revision));
CREATE TABLE program_applicability (id TEXT PRIMARY KEY, program_id TEXT NOT NULL REFERENCES programs(id), ref TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('excluded','included')), rationale TEXT NOT NULL, actor_id TEXT NOT NULL, actor_name TEXT NOT NULL, decided_at TEXT NOT NULL);
CREATE INDEX program_applicability_ref ON program_applicability(program_id,ref,decided_at);
CREATE TABLE program_reviews (id TEXT PRIMARY KEY, program_id TEXT NOT NULL REFERENCES programs(id), reviewer TEXT NOT NULL, notes TEXT NOT NULL, snapshot_hash TEXT NOT NULL, recorded_by TEXT NOT NULL, recorded_name TEXT NOT NULL, at TEXT NOT NULL);
CREATE TABLE edition_changes (
 id TEXT PRIMARY KEY, program_id TEXT NOT NULL REFERENCES programs(id), from_edition TEXT NOT NULL, to_edition TEXT NOT NULL, diff_json TEXT NOT NULL,
 proposed_by TEXT NOT NULL, proposed_name TEXT NOT NULL, proposed_at TEXT NOT NULL,
 decision TEXT CHECK(decision IN ('accepted','rejected')), decided_by TEXT, decided_name TEXT, decided_at TEXT, reason TEXT
);
CREATE TRIGGER edition_change_decided_once BEFORE UPDATE ON edition_changes WHEN OLD.decision IS NOT NULL BEGIN SELECT RAISE(ABORT,'decided_edition_change'); END;
CREATE UNIQUE INDEX edition_change_open ON edition_changes(program_id) WHERE decision IS NULL;
CREATE TABLE program_editions (id TEXT PRIMARY KEY, program_id TEXT NOT NULL REFERENCES programs(id), edition TEXT NOT NULL, effective_at TEXT NOT NULL, change_id TEXT REFERENCES edition_changes(id));

-- Shipped library controls adopted into this installation's controls.
CREATE TABLE library_adoptions (control_id TEXT PRIMARY KEY REFERENCES controls(id), library_id TEXT NOT NULL UNIQUE, library_revision INTEGER NOT NULL, adopted_at TEXT NOT NULL);

-- Reusable mappings and accountable ownership (PROGRAM-002).
CREATE TABLE control_mappings (id TEXT PRIMARY KEY, control_id TEXT NOT NULL REFERENCES controls(id), framework TEXT NOT NULL, edition TEXT NOT NULL, ref TEXT NOT NULL, added_by TEXT NOT NULL, added_name TEXT NOT NULL, added_at TEXT NOT NULL, reason TEXT NOT NULL, removed_by TEXT, removed_name TEXT, removed_at TEXT, removal_reason TEXT);
CREATE UNIQUE INDEX control_mapping_active ON control_mappings(control_id,framework,edition,ref) WHERE removed_at IS NULL;
CREATE TABLE control_owners (id TEXT PRIMARY KEY, control_id TEXT NOT NULL REFERENCES controls(id), owner_person_id TEXT NOT NULL REFERENCES people(id), contributors TEXT NOT NULL DEFAULT '[]', due_date TEXT, actor_id TEXT NOT NULL, actor_name TEXT NOT NULL, reason TEXT NOT NULL, at TEXT NOT NULL);
CREATE INDEX control_owners_control ON control_owners(control_id,at);
CREATE TABLE control_scope (id TEXT PRIMARY KEY, control_id TEXT NOT NULL REFERENCES controls(id), asset TEXT NOT NULL, action TEXT NOT NULL CHECK(action IN ('added','removed')), reason TEXT NOT NULL, effective_at TEXT NOT NULL, actor_id TEXT NOT NULL, actor_name TEXT NOT NULL);
CREATE INDEX control_scope_control ON control_scope(control_id,effective_at);
CREATE TRIGGER program_revisions_immutable BEFORE UPDATE ON program_revisions BEGIN SELECT RAISE(ABORT,'immutable_revision'); END;
CREATE TRIGGER program_applicability_immutable BEFORE UPDATE ON program_applicability BEGIN SELECT RAISE(ABORT,'immutable_decision'); END;
CREATE TRIGGER control_owners_immutable BEFORE UPDATE ON control_owners BEGIN SELECT RAISE(ABORT,'immutable_assignment'); END;
CREATE TRIGGER control_scope_immutable BEFORE UPDATE ON control_scope BEGIN SELECT RAISE(ABORT,'immutable_scope'); END;
CREATE TRIGGER control_scope_retained BEFORE DELETE ON control_scope BEGIN SELECT RAISE(ABORT,'immutable_scope'); END;

-- Annual, semi-annual and anchored renewal (CADENCE-001). Schedule revisions
-- apply from effective_from; a requirement without one keeps its own cadence.
CREATE TABLE requirement_schedules (
 id TEXT PRIMARY KEY, requirement_id TEXT NOT NULL REFERENCES requirements(id),
 cadence TEXT NOT NULL CHECK(cadence IN ('daily','weekly','monthly','quarterly','semi-annual','annual')),
 anchor TEXT NOT NULL CHECK(anchor IN ('calendar','effective-date','fiscal-year','audit-window')),
 fiscal_start_month INTEGER CHECK(fiscal_start_month BETWEEN 1 AND 12), window_start TEXT, program_id TEXT REFERENCES programs(id),
 reminder_lead_days INTEGER CHECK(reminder_lead_days BETWEEN 1 AND 365), owner_person_id TEXT REFERENCES people(id),
 effective_from TEXT NOT NULL, actor_id TEXT NOT NULL, actor_name TEXT NOT NULL, reason TEXT NOT NULL
);
CREATE INDEX requirement_schedules_requirement ON requirement_schedules(requirement_id,effective_from);
CREATE TRIGGER requirement_schedules_immutable BEFORE UPDATE ON requirement_schedules BEGIN SELECT RAISE(ABORT,'immutable_schedule'); END;
CREATE TABLE receipt_effective_dates (receipt_id TEXT PRIMARY KEY REFERENCES receipts(id), effective_date TEXT NOT NULL);
CREATE TRIGGER receipt_effective_immutable BEFORE UPDATE ON receipt_effective_dates BEGIN SELECT RAISE(ABORT,'immutable_receipt'); END;
CREATE TRIGGER receipt_effective_retained BEFORE DELETE ON receipt_effective_dates BEGIN SELECT RAISE(ABORT,'immutable_receipt'); END;
CREATE TABLE renewal_overrides (id TEXT PRIMARY KEY, requirement_id TEXT NOT NULL REFERENCES requirements(id), cycle_due TEXT NOT NULL, due_date TEXT NOT NULL, reason TEXT NOT NULL, actor_id TEXT NOT NULL, actor_name TEXT NOT NULL, at TEXT NOT NULL);

-- Durable follow-up sends (FOLLOWUP-001): one row per obligation, cycle and kind.
CREATE TABLE followups (
 id TEXT PRIMARY KEY, kind TEXT NOT NULL, subject_id TEXT NOT NULL, cycle_key TEXT NOT NULL, recipient TEXT NOT NULL,
 state TEXT NOT NULL CHECK(state IN ('pending','accepted','failed','uncertain','skipped')), detail TEXT NOT NULL DEFAULT '',
 created_at TEXT NOT NULL, attempted_at TEXT, UNIQUE(kind,subject_id,cycle_key)
);

-- Resources, continuous control tests and immutable observations (TEST-001,
-- API-001, COLLECTION-001). Pushed records are source-reported; collector reads
-- are source-observed; the two never merge.
CREATE TABLE resource_types (type TEXT PRIMARY KEY, schema_json TEXT NOT NULL, declared_by TEXT NOT NULL, declared_at TEXT NOT NULL);
CREATE TABLE resources (
 id TEXT PRIMARY KEY, type TEXT NOT NULL, unique_id TEXT NOT NULL, display_name TEXT NOT NULL,
 source_kind TEXT NOT NULL CHECK(source_kind IN ('source-reported','source-observed')), source_ref TEXT NOT NULL, source_label TEXT NOT NULL,
 attributes_json TEXT NOT NULL, attributes_hash TEXT NOT NULL, first_seen_at TEXT NOT NULL, updated_at TEXT NOT NULL, removed_at TEXT,
 -- Last successful source read (collectors only); a stale read makes tests unknown.
 observed_at TEXT,
 UNIQUE(type,unique_id)
);
CREATE TABLE resource_versions (id TEXT PRIMARY KEY, resource_id TEXT NOT NULL REFERENCES resources(id), change TEXT NOT NULL CHECK(change IN ('created','updated','removed','restored')), attributes_json TEXT NOT NULL, source_ref TEXT NOT NULL, at TEXT NOT NULL);
CREATE INDEX resource_versions_resource ON resource_versions(resource_id,at);
CREATE TRIGGER resource_versions_immutable BEFORE UPDATE ON resource_versions BEGIN SELECT RAISE(ABORT,'immutable_history'); END;
CREATE TRIGGER resource_versions_retained BEFORE DELETE ON resource_versions BEGIN SELECT RAISE(ABORT,'immutable_history'); END;

CREATE TABLE tests (
 id TEXT PRIMARY KEY, catalogue_id TEXT UNIQUE, name TEXT NOT NULL, resource_type TEXT NOT NULL,
 criteria_json TEXT NOT NULL, cadence TEXT NOT NULL CHECK(cadence IN ('hourly','daily')),
 category TEXT NOT NULL CHECK(category IN ('cloud','identity','code','device','vulnerability','security issue','personnel','policy','vendor')),
 severity TEXT NOT NULL CHECK(severity IN ('critical','high','medium','low')),
 origin TEXT NOT NULL CHECK(origin IN ('catalogue','custom','api')), defined_by TEXT NOT NULL,
 revision INTEGER NOT NULL DEFAULT 1, enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)), created_at TEXT NOT NULL
);
CREATE TABLE test_controls (test_id TEXT NOT NULL REFERENCES tests(id), control_id TEXT NOT NULL REFERENCES controls(id), PRIMARY KEY(test_id,control_id));
CREATE TABLE test_revisions (id TEXT PRIMARY KEY, test_id TEXT NOT NULL REFERENCES tests(id), revision INTEGER NOT NULL, criteria_json TEXT NOT NULL, excluded_json TEXT NOT NULL DEFAULT '[]', cadence TEXT NOT NULL, actor TEXT NOT NULL, reason TEXT NOT NULL, at TEXT NOT NULL, UNIQUE(test_id,revision));
CREATE TRIGGER test_revisions_immutable BEFORE UPDATE ON test_revisions BEGIN SELECT RAISE(ABORT,'immutable_revision'); END;
CREATE TABLE test_runs (
 id TEXT PRIMARY KEY, test_id TEXT NOT NULL REFERENCES tests(id), revision INTEGER NOT NULL,
 trigger TEXT NOT NULL CHECK(trigger IN ('schedule','source-change','manual','retest')),
 started_at TEXT NOT NULL, finished_at TEXT, outcome TEXT CHECK(outcome IN ('complete','failed')),
 population INTEGER NOT NULL DEFAULT 0, passed INTEGER NOT NULL DEFAULT 0, failed INTEGER NOT NULL DEFAULT 0, unknown INTEGER NOT NULL DEFAULT 0, not_applicable INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX test_runs_test ON test_runs(test_id,started_at);
CREATE TABLE observations (
 id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES test_runs(id), test_id TEXT NOT NULL REFERENCES tests(id), revision INTEGER NOT NULL,
 resource_id TEXT NOT NULL REFERENCES resources(id), result TEXT NOT NULL CHECK(result IN ('pass','fail','unknown','not applicable')),
 expected_json TEXT NOT NULL, actual_json TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '',
 source_kind TEXT NOT NULL, source_ref TEXT NOT NULL, observed_at TEXT NOT NULL, exception_id TEXT,
 -- The interval this observation stands for: since the test's previous run.
 interval_from TEXT
);
CREATE INDEX observations_item ON observations(test_id,resource_id,observed_at);
CREATE TRIGGER observations_immutable BEFORE UPDATE ON observations BEGIN SELECT RAISE(ABORT,'immutable_observation'); END;
CREATE TRIGGER observations_retained BEFORE DELETE ON observations BEGIN SELECT RAISE(ABORT,'immutable_observation'); END;
CREATE TABLE test_exceptions (id TEXT PRIMARY KEY, test_id TEXT NOT NULL REFERENCES tests(id), resource_id TEXT REFERENCES resources(id), reason TEXT NOT NULL, approved_by TEXT NOT NULL, approved_name TEXT NOT NULL, approved_at TEXT NOT NULL, expires_at TEXT NOT NULL, revoked_at TEXT, CHECK(expires_at > approved_at));

-- Remediation obligations, SLA policies and automatic re-tests (REMEDY-001/002).
CREATE TABLE sla_policies (id TEXT PRIMARY KEY, category TEXT NOT NULL, severity TEXT NOT NULL CHECK(severity IN ('critical','high','medium','low')), days INTEGER NOT NULL CHECK(days BETWEEN 1 AND 365), effective_at TEXT NOT NULL, actor_id TEXT NOT NULL, actor_name TEXT NOT NULL);
CREATE TRIGGER sla_policies_immutable BEFORE UPDATE ON sla_policies BEGIN SELECT RAISE(ABORT,'immutable_policy'); END;
CREATE TABLE obligations (
 id TEXT PRIMARY KEY, test_id TEXT NOT NULL REFERENCES tests(id), resource_id TEXT NOT NULL REFERENCES resources(id),
 severity TEXT NOT NULL, category TEXT NOT NULL,
 state TEXT NOT NULL CHECK(state IN ('open','awaiting verification','verified','risk accepted')),
 clock_started_at TEXT NOT NULL, sla_days INTEGER NOT NULL, sla_policy_id TEXT, opened_observation_id TEXT NOT NULL REFERENCES observations(id),
 owner_person_id TEXT REFERENCES people(id), next_action TEXT NOT NULL DEFAULT '', target_date TEXT,
 accepted_until TEXT, accepted_by TEXT, closed_at TEXT, verified_observation_id TEXT REFERENCES observations(id), cycles INTEGER NOT NULL DEFAULT 1,
 UNIQUE(test_id,resource_id)
);
CREATE TABLE obligation_events (id TEXT PRIMARY KEY, obligation_id TEXT NOT NULL REFERENCES obligations(id), kind TEXT NOT NULL, actor_id TEXT NOT NULL, actor_name TEXT NOT NULL, body TEXT NOT NULL DEFAULT '', observation_id TEXT, at TEXT NOT NULL);
CREATE INDEX obligation_events_obligation ON obligation_events(obligation_id,at);
CREATE TRIGGER obligation_events_immutable BEFORE UPDATE ON obligation_events BEGIN SELECT RAISE(ABORT,'immutable_event'); END;
CREATE TRIGGER obligation_events_retained BEFORE DELETE ON obligation_events BEGIN SELECT RAISE(ABORT,'immutable_event'); END;
CREATE TABLE retests (id TEXT PRIMARY KEY, obligation_id TEXT NOT NULL REFERENCES obligations(id), reason TEXT NOT NULL, queued_at TEXT NOT NULL, run_id TEXT REFERENCES test_runs(id), done_at TEXT);
CREATE UNIQUE INDEX retests_pending ON retests(obligation_id) WHERE done_at IS NULL;

-- Public REST API tokens (API-001). Only SHA-256 digests are stored; a token
-- never approves or publishes. Every call is recorded without the token.
CREATE TABLE api_tokens (
 id TEXT PRIMARY KEY, name TEXT NOT NULL, scopes TEXT NOT NULL, token_hash TEXT UNIQUE,
 created_by TEXT NOT NULL, created_name TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL,
 revoked_at TEXT, revoked_by TEXT,
 CHECK (token_hash IS NULL OR (length(token_hash)=64 AND token_hash NOT GLOB '*[^a-f0-9]*'))
);
CREATE TRIGGER api_token_revocation_only BEFORE UPDATE ON api_tokens
 WHEN NEW.id IS NOT OLD.id OR NEW.scopes IS NOT OLD.scopes OR NEW.token_hash IS NOT OLD.token_hash OR NEW.expires_at IS NOT OLD.expires_at OR OLD.revoked_at IS NOT NULL
 BEGIN SELECT RAISE(ABORT,'immutable_api_token'); END;
CREATE TABLE api_calls (id TEXT PRIMARY KEY, token_id TEXT, method TEXT NOT NULL, route TEXT NOT NULL, status INTEGER NOT NULL, at TEXT NOT NULL);
CREATE INDEX api_calls_token ON api_calls(token_id,at);
CREATE TRIGGER api_calls_immutable BEFORE UPDATE ON api_calls BEGIN SELECT RAISE(ABORT,'immutable_audit'); END;
CREATE TABLE api_rate (token_id TEXT NOT NULL, window TEXT NOT NULL, count INTEGER NOT NULL, PRIMARY KEY(token_id,window));
CREATE TABLE api_evidence (receipt_id TEXT PRIMARY KEY REFERENCES receipts(id), token_id TEXT NOT NULL REFERENCES api_tokens(id), token_name TEXT NOT NULL, owner_name TEXT NOT NULL);

-- Read-only provider connections and scheduled collection (CONNECT-001,
-- COLLECTION-001). Credentials are AES-GCM ciphertext under an installation key;
-- archives never carry them and restored connections stay inactive.
CREATE TABLE connections (
 id TEXT PRIMARY KEY, provider TEXT NOT NULL CHECK(provider IN ('github')), label TEXT NOT NULL, account TEXT NOT NULL, api_base TEXT NOT NULL,
 secret_ciphertext TEXT, secret_iv TEXT, granted_scopes TEXT NOT NULL DEFAULT '[]',
 status TEXT NOT NULL CHECK(status IN ('active','revoked','needs reconnect','inactive after restore')),
 created_by TEXT NOT NULL, created_name TEXT NOT NULL, created_at TEXT NOT NULL, rotated_at TEXT, revoked_at TEXT,
 last_success_at TEXT, last_attempt_at TEXT, next_attempt_at TEXT, backoff_seconds INTEGER NOT NULL DEFAULT 0, last_error TEXT NOT NULL DEFAULT ''
);
CREATE TABLE connection_repositories (connection_id TEXT NOT NULL REFERENCES connections(id), full_name TEXT NOT NULL, selected INTEGER NOT NULL CHECK(selected IN (0,1)), PRIMARY KEY(connection_id,full_name));
CREATE TABLE collection_runs (
 id TEXT PRIMARY KEY, connection_id TEXT NOT NULL REFERENCES connections(id), trigger TEXT NOT NULL CHECK(trigger IN ('schedule','manual')),
 connector_revision TEXT NOT NULL, started_at TEXT NOT NULL, finished_at TEXT,
 outcome TEXT CHECK(outcome IN ('complete','partial','failed','throttled')), coverage_json TEXT NOT NULL DEFAULT '{}', error_code TEXT NOT NULL DEFAULT ''
);
CREATE INDEX collection_runs_connection ON collection_runs(connection_id,started_at);
CREATE UNIQUE INDEX collection_run_claim ON collection_runs(connection_id) WHERE finished_at IS NULL;

-- Risk register (RISK-001/002) and the vendor records risks link to.
CREATE TABLE risk_methods (id TEXT PRIMARY KEY, revision INTEGER NOT NULL UNIQUE, scale INTEGER NOT NULL CHECK(scale BETWEEN 3 AND 5), likelihood_labels TEXT NOT NULL, impact_labels TEXT NOT NULL, formula TEXT NOT NULL CHECK(formula IN ('product','matrix')), matrix_json TEXT NOT NULL DEFAULT '[]', thresholds_json TEXT NOT NULL, actor_name TEXT NOT NULL, at TEXT NOT NULL);
CREATE TRIGGER risk_methods_immutable BEFORE UPDATE ON risk_methods BEGIN SELECT RAISE(ABORT,'immutable_method'); END;
CREATE TABLE vendors (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE COLLATE NOCASE, owner_person_id TEXT REFERENCES people(id), data_access TEXT NOT NULL DEFAULT '', criticality TEXT NOT NULL CHECK(criticality IN ('low','medium','high','critical')), review_due TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE risk_imports (id TEXT PRIMARY KEY, filename TEXT NOT NULL, sha256 TEXT NOT NULL, admitted INTEGER NOT NULL, refused INTEGER NOT NULL, actor_name TEXT NOT NULL, at TEXT NOT NULL);
CREATE TABLE risks (
 id TEXT PRIMARY KEY, title TEXT NOT NULL, scenario TEXT NOT NULL, library_id TEXT,
 origin TEXT NOT NULL CHECK(origin IN ('library','import','form','api')), import_id TEXT REFERENCES risk_imports(id), source_label TEXT NOT NULL,
 owner_person_id TEXT REFERENCES people(id), assets TEXT NOT NULL DEFAULT '[]', treatment TEXT NOT NULL CHECK(treatment IN ('mitigate','accept','transfer','avoid')),
 review_due TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE TABLE risk_assessments (id TEXT PRIMARY KEY, risk_id TEXT NOT NULL REFERENCES risks(id), kind TEXT NOT NULL CHECK(kind IN ('inherent','residual')), method_revision INTEGER NOT NULL, likelihood INTEGER NOT NULL, impact INTEGER NOT NULL, score INTEGER NOT NULL, level TEXT NOT NULL, likelihood_label TEXT NOT NULL, impact_label TEXT NOT NULL, notes TEXT NOT NULL DEFAULT '', actor_name TEXT NOT NULL, at TEXT NOT NULL);
CREATE TRIGGER risk_assessments_immutable BEFORE UPDATE ON risk_assessments BEGIN SELECT RAISE(ABORT,'immutable_assessment'); END;
CREATE TRIGGER risk_assessments_retained BEFORE DELETE ON risk_assessments BEGIN SELECT RAISE(ABORT,'immutable_assessment'); END;
CREATE TABLE risk_links (risk_id TEXT NOT NULL REFERENCES risks(id), kind TEXT NOT NULL CHECK(kind IN ('control','test','vendor','incident','asset')), target TEXT NOT NULL, added_at TEXT NOT NULL, PRIMARY KEY(risk_id,kind,target));
CREATE TABLE risk_treatments (id TEXT PRIMARY KEY, risk_id TEXT NOT NULL REFERENCES risks(id), title TEXT NOT NULL, owner_person_id TEXT REFERENCES people(id), due_date TEXT NOT NULL, verification_test_id TEXT REFERENCES tests(id), status TEXT NOT NULL CHECK(status IN ('open','done','verified')), evidence TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL);
CREATE TABLE risk_acceptances (id TEXT PRIMARY KEY, risk_id TEXT NOT NULL REFERENCES risks(id), assessment_id TEXT NOT NULL REFERENCES risk_assessments(id), rationale TEXT NOT NULL, approver_name TEXT NOT NULL, approved_by TEXT NOT NULL, approved_at TEXT NOT NULL, expires_at TEXT NOT NULL, escalated_at TEXT, CHECK(expires_at > approved_at));

-- Policy register with exact-revision approval (POLICY-001 core). A revision's
-- text never changes; a changed draft is a new revision needing a new decision.
CREATE TABLE policies (id TEXT PRIMARY KEY, title TEXT NOT NULL UNIQUE COLLATE NOCASE, owner_person_id TEXT REFERENCES people(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE policy_revisions (
 id TEXT PRIMARY KEY, policy_id TEXT NOT NULL REFERENCES policies(id), version INTEGER NOT NULL, body TEXT NOT NULL, body_sha256 TEXT NOT NULL,
 status TEXT NOT NULL CHECK(status IN ('draft','approved','rejected','published','superseded')),
 drafted_by TEXT NOT NULL, drafted_at TEXT NOT NULL, decided_by TEXT, decided_at TEXT, decision_note TEXT, approved_sha256 TEXT,
 published_at TEXT, effective_date TEXT, review_due TEXT, UNIQUE(policy_id,version)
);
CREATE TRIGGER policy_revision_text_immutable BEFORE UPDATE ON policy_revisions WHEN NEW.body IS NOT OLD.body OR NEW.body_sha256 IS NOT OLD.body_sha256 OR NEW.version IS NOT OLD.version OR NEW.policy_id IS NOT OLD.policy_id BEGIN SELECT RAISE(ABORT,'immutable_policy_revision'); END;
CREATE TRIGGER policy_revision_retained BEFORE DELETE ON policy_revisions BEGIN SELECT RAISE(ABORT,'immutable_policy_revision'); END;

-- Remediation tickets in Vector and external trackers (WORK-001). Each
-- destination holds its own issue-write credential, sealed under the
-- installation key and never shared with collection. Tickets mirror tracker
-- assignee and status; a closed ticket only queues a re-test.
CREATE TABLE tracker_destinations (
 id TEXT PRIMARY KEY, provider TEXT NOT NULL CHECK(provider IN ('vector','jira','linear','github','asana')),
 label TEXT NOT NULL, api_base TEXT NOT NULL, account TEXT NOT NULL, project TEXT NOT NULL, project_name TEXT NOT NULL DEFAULT '',
 mapping_json TEXT NOT NULL DEFAULT '{}', secret_ciphertext TEXT, secret_iv TEXT, hook_ciphertext TEXT, hook_iv TEXT, hook_audience TEXT NOT NULL DEFAULT '',
 status TEXT NOT NULL CHECK(status IN ('active','revoked','needs reconnect','inactive after restore')),
 created_by TEXT NOT NULL, created_name TEXT NOT NULL, created_at TEXT NOT NULL, rotated_at TEXT, revoked_at TEXT,
 last_success_at TEXT, last_error TEXT NOT NULL DEFAULT ''
);
CREATE TABLE tickets (
 id TEXT PRIMARY KEY, obligation_id TEXT NOT NULL REFERENCES obligations(id), destination_id TEXT NOT NULL REFERENCES tracker_destinations(id),
 remote_id TEXT, remote_key TEXT, remote_url TEXT, created_at TEXT NOT NULL, created_name TEXT NOT NULL,
 sync_state TEXT NOT NULL CHECK(sync_state IN ('creating','linked','creation uncertain','mapping failed','authorization lost','remote deleted','conflict','sync failed')),
 sync_error TEXT NOT NULL DEFAULT '', remote_status TEXT NOT NULL DEFAULT '', remote_closed INTEGER NOT NULL DEFAULT 0 CHECK(remote_closed IN (0,1)),
 remote_assignee TEXT, remote_due TEXT, synced_due TEXT, last_synced_at TEXT, last_attempt_at TEXT,
 UNIQUE(obligation_id,destination_id)
);
CREATE UNIQUE INDEX tickets_remote ON tickets(destination_id,remote_id) WHERE remote_id IS NOT NULL;
CREATE TABLE ticket_events (id TEXT PRIMARY KEY, ticket_id TEXT NOT NULL REFERENCES tickets(id), kind TEXT NOT NULL, remote_value TEXT, local_value TEXT, detail TEXT NOT NULL DEFAULT '', trigger TEXT NOT NULL, at TEXT NOT NULL);
CREATE INDEX ticket_events_ticket ON ticket_events(ticket_id,at);
CREATE TRIGGER ticket_events_immutable BEFORE UPDATE ON ticket_events BEGIN SELECT RAISE(ABORT,'immutable_event'); END;
CREATE TRIGGER ticket_events_retained BEFORE DELETE ON ticket_events BEGIN SELECT RAISE(ABORT,'immutable_event'); END;
-- Remote comments already mirrored (either direction) are never mirrored twice.
CREATE TABLE ticket_comments (ticket_id TEXT NOT NULL REFERENCES tickets(id), remote_comment_id TEXT NOT NULL, direction TEXT NOT NULL CHECK(direction IN ('in','out')), at TEXT NOT NULL, PRIMARY KEY(ticket_id,remote_comment_id));
-- Inbound webhook deliveries: a redelivered or replayed event is admitted once.
CREATE TABLE tracker_deliveries (destination_id TEXT NOT NULL REFERENCES tracker_destinations(id), delivery_id TEXT NOT NULL, ticket_ref TEXT NOT NULL DEFAULT '', outcome TEXT NOT NULL, received_at TEXT NOT NULL, PRIMARY KEY(destination_id,delivery_id));

-- Daily readiness snapshots per program (READINESS-001 trend history). A
-- snapshot records what readiness reported that day; it is never recomputed.
CREATE TABLE readiness_snapshots (program_id TEXT NOT NULL REFERENCES programs(id), day TEXT NOT NULL, totals_json TEXT NOT NULL, taken_at TEXT NOT NULL, PRIMARY KEY(program_id,day));
CREATE TRIGGER readiness_snapshots_immutable BEFORE UPDATE ON readiness_snapshots BEGIN SELECT RAISE(ABORT,'immutable_snapshot'); END;

-- FOLLOWUP-001 channels and rules. Slack bot tokens and Teams workflow URLs are
-- credentials: sealed under the installation key, never archived. Without a
-- settings row, sends are immediate and the digest uses its defaults.
ALTER TABLE followups ADD COLUMN channel TEXT NOT NULL DEFAULT 'email';
CREATE TABLE followup_settings (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1), timezone TEXT NOT NULL, calendar_enabled INTEGER NOT NULL CHECK(calendar_enabled IN (0,1)),
 business_days TEXT NOT NULL, holidays TEXT NOT NULL DEFAULT '[]', quiet_start TEXT NOT NULL, quiet_end TEXT NOT NULL,
 digest_enabled INTEGER NOT NULL CHECK(digest_enabled IN (0,1)), digest_day INTEGER NOT NULL CHECK(digest_day BETWEEN 0 AND 6), digest_time TEXT NOT NULL,
 repeat_days INTEGER NOT NULL CHECK(repeat_days BETWEEN 0 AND 30), escalate_after_days INTEGER NOT NULL CHECK(escalate_after_days BETWEEN 0 AND 60), escalation_person_id TEXT REFERENCES people(id),
 updated_by TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE TABLE followup_channels (
 id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('slack','teams')), label TEXT NOT NULL, account TEXT NOT NULL, target TEXT NOT NULL DEFAULT '',
 secret_ciphertext TEXT, secret_iv TEXT, status TEXT NOT NULL CHECK(status IN ('active','revoked','needs reconnect','inactive after restore')),
 created_by TEXT NOT NULL, created_name TEXT NOT NULL, created_at TEXT NOT NULL, rotated_at TEXT, revoked_at TEXT, last_success_at TEXT, last_error TEXT NOT NULL DEFAULT ''
);
CREATE UNIQUE INDEX followup_channel_kind ON followup_channels(kind) WHERE status='active';
CREATE TABLE notify_preferences (person_id TEXT PRIMARY KEY REFERENCES people(id), via TEXT NOT NULL CHECK(via IN ('email','slack','teams')), all_clear INTEGER NOT NULL DEFAULT 0 CHECK(all_clear IN (0,1)), updated_by TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE followup_pauses (id TEXT PRIMARY KEY, subject_id TEXT NOT NULL, reason TEXT NOT NULL, paused_by TEXT NOT NULL, paused_at TEXT NOT NULL, resumed_by TEXT, resumed_at TEXT);
CREATE UNIQUE INDEX followup_pause_active ON followup_pauses(subject_id) WHERE resumed_at IS NULL;

-- CLOUD-001: connections admit AWS beside GitHub, with per-connection read
-- configuration (regions, role to assume, member-account read role). SQLite
-- cannot change a CHECK in place, so the table is rebuilt. Its child rows are
-- set aside first (with their row order) and restored after, so no foreign key
-- is ever left dangling and every run and repository selection is kept.
CREATE TABLE migrate_collection_runs AS SELECT rowid AS kept_rowid,id,connection_id,trigger,connector_revision,started_at,finished_at,outcome,coverage_json,error_code FROM collection_runs;
CREATE TABLE migrate_connection_repositories AS SELECT rowid AS kept_rowid,connection_id,full_name,selected FROM connection_repositories;
DELETE FROM collection_runs;
DELETE FROM connection_repositories;
CREATE TABLE connections_rebuilt (
 id TEXT PRIMARY KEY, provider TEXT NOT NULL CHECK(provider IN ('github','aws')), label TEXT NOT NULL, account TEXT NOT NULL, api_base TEXT NOT NULL,
 secret_ciphertext TEXT, secret_iv TEXT, granted_scopes TEXT NOT NULL DEFAULT '[]',
 status TEXT NOT NULL CHECK(status IN ('active','revoked','needs reconnect','inactive after restore')),
 created_by TEXT NOT NULL, created_name TEXT NOT NULL, created_at TEXT NOT NULL, rotated_at TEXT, revoked_at TEXT,
 last_success_at TEXT, last_attempt_at TEXT, next_attempt_at TEXT, backoff_seconds INTEGER NOT NULL DEFAULT 0, last_error TEXT NOT NULL DEFAULT '',
 config_json TEXT NOT NULL DEFAULT '{}'
);
INSERT INTO connections_rebuilt(rowid,id,provider,label,account,api_base,secret_ciphertext,secret_iv,granted_scopes,status,created_by,created_name,created_at,rotated_at,revoked_at,last_success_at,last_attempt_at,next_attempt_at,backoff_seconds,last_error)
 SELECT rowid,id,provider,label,account,api_base,secret_ciphertext,secret_iv,granted_scopes,status,created_by,created_name,created_at,rotated_at,revoked_at,last_success_at,last_attempt_at,next_attempt_at,backoff_seconds,last_error FROM connections;
DROP TABLE connections;
ALTER TABLE connections_rebuilt RENAME TO connections;
INSERT INTO connection_repositories(rowid,connection_id,full_name,selected) SELECT kept_rowid,connection_id,full_name,selected FROM migrate_connection_repositories;
INSERT INTO collection_runs(rowid,id,connection_id,trigger,connector_revision,started_at,finished_at,outcome,coverage_json,error_code) SELECT kept_rowid,id,connection_id,trigger,connector_revision,started_at,finished_at,outcome,coverage_json,error_code FROM migrate_collection_runs;
DROP TABLE migrate_connection_repositories;
DROP TABLE migrate_collection_runs;

-- IDENTITY-001: connections admit directory providers (Okta, Google Workspace,
-- Microsoft Entra ID, JumpCloud). The provider CHECK is dropped so later
-- connectors need no rebuild; the application admits only listed providers.
-- SQLite cannot drop a CHECK in place, so the table is rebuilt. Its child rows are
-- set aside first (with their row order) and restored after, so no foreign key
-- is ever left dangling and every run and repository selection is kept.
CREATE TABLE migrate_collection_runs AS SELECT rowid AS kept_rowid,id,connection_id,trigger,connector_revision,started_at,finished_at,outcome,coverage_json,error_code FROM collection_runs;
CREATE TABLE migrate_connection_repositories AS SELECT rowid AS kept_rowid,connection_id,full_name,selected FROM connection_repositories;
DELETE FROM collection_runs;
DELETE FROM connection_repositories;
CREATE TABLE connections_rebuilt (
 id TEXT PRIMARY KEY, provider TEXT NOT NULL, label TEXT NOT NULL, account TEXT NOT NULL, api_base TEXT NOT NULL,
 secret_ciphertext TEXT, secret_iv TEXT, granted_scopes TEXT NOT NULL DEFAULT '[]',
 status TEXT NOT NULL CHECK(status IN ('active','revoked','needs reconnect','inactive after restore')),
 created_by TEXT NOT NULL, created_name TEXT NOT NULL, created_at TEXT NOT NULL, rotated_at TEXT, revoked_at TEXT,
 last_success_at TEXT, last_attempt_at TEXT, next_attempt_at TEXT, backoff_seconds INTEGER NOT NULL DEFAULT 0, last_error TEXT NOT NULL DEFAULT '',
 config_json TEXT NOT NULL DEFAULT '{}'
);
INSERT INTO connections_rebuilt(rowid,id,provider,label,account,api_base,secret_ciphertext,secret_iv,granted_scopes,status,created_by,created_name,created_at,rotated_at,revoked_at,last_success_at,last_attempt_at,next_attempt_at,backoff_seconds,last_error,config_json)
 SELECT rowid,id,provider,label,account,api_base,secret_ciphertext,secret_iv,granted_scopes,status,created_by,created_name,created_at,rotated_at,revoked_at,last_success_at,last_attempt_at,next_attempt_at,backoff_seconds,last_error,config_json FROM connections;
DROP TABLE connections;
ALTER TABLE connections_rebuilt RENAME TO connections;
INSERT INTO connection_repositories(rowid,connection_id,full_name,selected) SELECT kept_rowid,connection_id,full_name,selected FROM migrate_connection_repositories;
INSERT INTO collection_runs(rowid,id,connection_id,trigger,connector_revision,started_at,finished_at,outcome,coverage_json,error_code) SELECT kept_rowid,id,connection_id,trigger,connector_revision,started_at,finished_at,outcome,coverage_json,error_code FROM migrate_collection_runs;
DROP TABLE migrate_connection_repositories;
DROP TABLE migrate_collection_runs;
-- Reviewable identity matches: a directory account is proposed for a person by
-- email, and an owner approves, rejects or chooses another person. Accounts
-- without a decision stay visible as unmatched.
CREATE TABLE identity_matches (
 resource_id TEXT PRIMARY KEY REFERENCES resources(id), person_id TEXT REFERENCES people(id),
 state TEXT NOT NULL CHECK(state IN ('proposed','approved','rejected')), basis TEXT NOT NULL,
 proposed_at TEXT NOT NULL, decided_by TEXT, decided_at TEXT, reason TEXT NOT NULL DEFAULT ''
);

-- POLICY-001 template links and ATTEST-001 attestations. An acknowledgment is
-- made only by the signed-in person and binds the exact revision fingerprint;
-- it is never changed or deleted. Departed people keep their history.
ALTER TABLE policies ADD COLUMN template_id TEXT;
CREATE TABLE policy_assignments (
 id TEXT PRIMARY KEY, policy_id TEXT NOT NULL REFERENCES policies(id), revision_id TEXT NOT NULL REFERENCES policy_revisions(id), person_id TEXT NOT NULL REFERENCES people(id),
 assigned_by TEXT NOT NULL, assigned_at TEXT NOT NULL, due_date TEXT NOT NULL,
 state TEXT NOT NULL CHECK(state IN ('pending','acknowledged','superseded','departed')), closed_at TEXT,
 UNIQUE(revision_id,person_id)
);
CREATE TABLE policy_acknowledgments (
 id TEXT PRIMARY KEY, assignment_id TEXT NOT NULL UNIQUE REFERENCES policy_assignments(id), person_id TEXT NOT NULL REFERENCES people(id),
 operator_id TEXT NOT NULL, operator_email TEXT NOT NULL, revision_id TEXT NOT NULL REFERENCES policy_revisions(id), version INTEGER NOT NULL, body_sha256 TEXT NOT NULL, acknowledged_at TEXT NOT NULL
);
CREATE TRIGGER policy_acknowledgments_immutable BEFORE UPDATE ON policy_acknowledgments BEGIN SELECT RAISE(ABORT,'immutable_acknowledgment'); END;
CREATE TRIGGER policy_acknowledgments_retained BEFORE DELETE ON policy_acknowledgments BEGIN SELECT RAISE(ABORT,'immutable_acknowledgment'); END;
CREATE TABLE policy_exceptions (id TEXT PRIMARY KEY, policy_id TEXT NOT NULL REFERENCES policies(id), person_id TEXT REFERENCES people(id), reason TEXT NOT NULL, approved_by TEXT NOT NULL, approved_at TEXT NOT NULL, expires_at TEXT NOT NULL, CHECK(expires_at > approved_at));
CREATE TABLE people_departures (person_id TEXT PRIMARY KEY REFERENCES people(id), departed_at TEXT NOT NULL, recorded_by TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '', access_outcome TEXT NOT NULL DEFAULT '');

-- CADENCE-001 recurring reviews of policies and vendors. Schedules are
-- revisions that apply from their effective time; a completed review is an
-- owner-asserted date; a one-off renewal date moves only the current cycle.
CREATE TABLE review_schedules (
 id TEXT PRIMARY KEY, subject_kind TEXT NOT NULL CHECK(subject_kind IN ('policy','vendor')), subject_id TEXT NOT NULL,
 cadence TEXT NOT NULL CHECK(cadence IN ('semi-annual','annual')), anchor TEXT NOT NULL CHECK(anchor IN ('effective-date','fiscal-year','audit-window')),
 fiscal_start_month INTEGER, window_start TEXT, program_id TEXT REFERENCES programs(id), reminder_lead_days INTEGER, owner_person_id TEXT REFERENCES people(id),
 effective_from TEXT NOT NULL, actor_id TEXT NOT NULL, actor_name TEXT NOT NULL, reason TEXT NOT NULL
);
CREATE TRIGGER review_schedules_immutable BEFORE UPDATE ON review_schedules BEGIN SELECT RAISE(ABORT,'immutable_schedule'); END;
CREATE TABLE review_completions (id TEXT PRIMARY KEY, subject_kind TEXT NOT NULL, subject_id TEXT NOT NULL, completed_on TEXT NOT NULL, notes TEXT NOT NULL, recorded_by TEXT NOT NULL, recorded_at TEXT NOT NULL);
CREATE TRIGGER review_completions_immutable BEFORE UPDATE ON review_completions BEGIN SELECT RAISE(ABORT,'immutable_review'); END;
CREATE TABLE review_overrides (id TEXT PRIMARY KEY, subject_kind TEXT NOT NULL, subject_id TEXT NOT NULL, cycle_due TEXT NOT NULL, due_date TEXT NOT NULL, reason TEXT NOT NULL, actor_name TEXT NOT NULL, at TEXT NOT NULL);

-- POPULATION-001 labelled CSV populations. Each upload is a manually-asserted
-- exhibit kept with its digest; its rows never change and never count as a
-- source read. Matches to People are reviewable decisions.
CREATE TABLE population_uploads (
 id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('roster','accounts','devices')), source_system TEXT NOT NULL, as_of TEXT NOT NULL, refresh_days INTEGER NOT NULL CHECK(refresh_days BETWEEN 1 AND 366),
 filename TEXT NOT NULL, sha256 TEXT NOT NULL, size INTEGER NOT NULL, object_key TEXT NOT NULL UNIQUE, mapping_json TEXT NOT NULL,
