-- ACCESS-001 access-review campaigns over a frozen population. Decisions are
-- appended, never changed; a revocation closes only on a fresh source read or
-- a newer uploaded list that no longer has the account.
CREATE TABLE access_reviews (
 id TEXT PRIMARY KEY, name TEXT NOT NULL, cadence TEXT NOT NULL CHECK(cadence IN ('quarterly','semi-annual','annual','one-off')),
 period_from TEXT NOT NULL, period_to TEXT NOT NULL, due_date TEXT NOT NULL, sources_json TEXT NOT NULL, reviewers_json TEXT NOT NULL,
 created_by TEXT NOT NULL, created_name TEXT NOT NULL, created_at TEXT NOT NULL, completed_at TEXT, previous_id TEXT REFERENCES access_reviews(id)
);
CREATE TABLE access_review_items (
 id TEXT PRIMARY KEY, review_id TEXT NOT NULL REFERENCES access_reviews(id), source TEXT NOT NULL, source_label TEXT NOT NULL, provenance TEXT NOT NULL CHECK(provenance IN ('source-observed','manually-asserted')),
 subject_ref TEXT NOT NULL, account_key TEXT NOT NULL, display_name TEXT NOT NULL, attributes_json TEXT NOT NULL, reviewer_person_id TEXT REFERENCES people(id), supplemental INTEGER NOT NULL DEFAULT 0, added_at TEXT NOT NULL,
 UNIQUE(review_id,source,account_key)
);
CREATE TRIGGER access_review_items_frozen BEFORE UPDATE ON access_review_items BEGIN SELECT RAISE(ABORT,'frozen_population'); END;
CREATE TABLE access_decisions (id TEXT PRIMARY KEY, item_id TEXT NOT NULL REFERENCES access_review_items(id), decision TEXT NOT NULL CHECK(decision IN ('retain','revoke','change','excluded')), reason TEXT NOT NULL, decided_by_person TEXT, decided_by_name TEXT NOT NULL, decided_by_email TEXT NOT NULL, at TEXT NOT NULL);
CREATE TRIGGER access_decisions_immutable BEFORE UPDATE ON access_decisions BEGIN SELECT RAISE(ABORT,'immutable_decision'); END;
CREATE TABLE access_delegations (item_id TEXT PRIMARY KEY REFERENCES access_review_items(id), to_person_id TEXT NOT NULL REFERENCES people(id), reason TEXT NOT NULL, by_name TEXT NOT NULL, at TEXT NOT NULL);
CREATE TABLE access_revocations (item_id TEXT PRIMARY KEY REFERENCES access_review_items(id), state TEXT NOT NULL CHECK(state IN ('requested','unresolved','verified')), requested_at TEXT NOT NULL, checked_at TEXT, verified_at TEXT, evidence TEXT NOT NULL DEFAULT '');

-- TRAIN-001 training: adopted course revisions, campaigns with schedule
-- history, assignments per cycle, graded attempts and completions with their
-- provenance. An assignment is never a completion; attempts and completions
-- are never changed.
ALTER TABLE people ADD COLUMN role TEXT;
CREATE TABLE training_adoptions (course_id TEXT NOT NULL, revision INTEGER NOT NULL, adopted_by TEXT NOT NULL, adopted_at TEXT NOT NULL, PRIMARY KEY(course_id,revision));
CREATE TABLE training_campaigns (
 id TEXT PRIMARY KEY, name TEXT NOT NULL, course_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('onboarding','recurring')),
 audience TEXT NOT NULL CHECK(audience IN ('everyone','employees','contractors','engineering')), due_days INTEGER NOT NULL CHECK(due_days BETWEEN 1 AND 365), interval_months INTEGER NOT NULL CHECK(interval_months BETWEEN 1 AND 36),
 created_by TEXT NOT NULL, created_name TEXT NOT NULL, created_at TEXT NOT NULL
);
CREATE TABLE training_schedule_changes (id TEXT PRIMARY KEY, campaign_id TEXT NOT NULL REFERENCES training_campaigns(id), due_days INTEGER NOT NULL, interval_months INTEGER NOT NULL, reason TEXT NOT NULL, actor_name TEXT NOT NULL, at TEXT NOT NULL);
CREATE TABLE training_assignments (
 id TEXT PRIMARY KEY, campaign_id TEXT NOT NULL REFERENCES training_campaigns(id), course_id TEXT NOT NULL, revision INTEGER NOT NULL, person_id TEXT NOT NULL REFERENCES people(id),
 cycle TEXT NOT NULL, assigned_at TEXT NOT NULL, due_date TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('assigned','completed','departed')), completed_at TEXT, completion_id TEXT,
 UNIQUE(campaign_id,person_id,cycle)
);
CREATE TABLE training_attempts (id TEXT PRIMARY KEY, person_id TEXT NOT NULL REFERENCES people(id), course_id TEXT NOT NULL, revision INTEGER NOT NULL, answers_json TEXT NOT NULL, score INTEGER NOT NULL, passed INTEGER NOT NULL, operator_email TEXT NOT NULL, at TEXT NOT NULL);
CREATE TRIGGER training_attempts_immutable BEFORE UPDATE ON training_attempts BEGIN SELECT RAISE(ABORT,'immutable_attempt'); END;
CREATE TRIGGER training_attempts_retained BEFORE DELETE ON training_attempts BEGIN SELECT RAISE(ABORT,'immutable_attempt'); END;
CREATE TABLE internal_courses (id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL, counts_as TEXT, approved_by TEXT NOT NULL, approved_at TEXT NOT NULL);
CREATE TABLE training_completions (
 id TEXT PRIMARY KEY, person_id TEXT NOT NULL REFERENCES people(id), course_id TEXT, course_title TEXT NOT NULL, revision INTEGER,
 source TEXT NOT NULL CHECK(source IN ('evidence','internal','knowbe4')), provenance TEXT NOT NULL, score INTEGER, attempt_id TEXT REFERENCES training_attempts(id), external_ref TEXT,
 recorded_by TEXT NOT NULL, completed_at TEXT NOT NULL, recorded_at TEXT NOT NULL
);
CREATE UNIQUE INDEX training_completion_source ON training_completions(source,external_ref) WHERE external_ref IS NOT NULL;
CREATE TRIGGER training_completions_immutable BEFORE UPDATE ON training_completions BEGIN SELECT RAISE(ABORT,'immutable_completion'); END;

-- WORK-002 ticket granularity. A whole-test ticket is one remote ticket shared
-- by every failing item of a test, each item keeping its own ticket row so
-- closing the remote ticket re-tests every item. Settings are per test, with
-- a default for new tests.
DROP INDEX tickets_remote;
CREATE INDEX tickets_remote_lookup ON tickets(destination_id,remote_id) WHERE remote_id IS NOT NULL;
ALTER TABLE tickets ADD COLUMN group_id TEXT;
CREATE TABLE ticket_settings (test_id TEXT PRIMARY KEY REFERENCES tests(id), destination_id TEXT NOT NULL REFERENCES tracker_destinations(id), granularity TEXT NOT NULL CHECK(granularity IN ('item','test')), auto_create INTEGER NOT NULL CHECK(auto_create IN (0,1)), follow_up TEXT NOT NULL CHECK(follow_up IN ('reopen','new')), updated_by TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE ticket_defaults (singleton INTEGER PRIMARY KEY CHECK(singleton=1), destination_id TEXT REFERENCES tracker_destinations(id), granularity TEXT NOT NULL CHECK(granularity IN ('item','test')), auto_create INTEGER NOT NULL CHECK(auto_create IN (0,1)), follow_up TEXT NOT NULL CHECK(follow_up IN ('reopen','new')), updated_by TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE ticket_groups (
 id TEXT PRIMARY KEY, test_id TEXT NOT NULL REFERENCES tests(id), destination_id TEXT NOT NULL REFERENCES tracker_destinations(id), remote_id TEXT, remote_key TEXT, remote_url TEXT,
 created_at TEXT NOT NULL, created_name TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('open','resolved','followed up')), item_list TEXT NOT NULL DEFAULT '', handled_close_at TEXT, due_written TEXT
);

-- A custom test's own fix step, shown beside every failing item of the test
-- (catalogue tests carry theirs in the catalogue). Null when none is written.
ALTER TABLE tests ADD COLUMN remediation TEXT;

-- RISK-002: versioned scale definitions and provenance. Legacy definitions
-- remain explicitly unrecorded; no historic assessment is rescored.
ALTER TABLE risk_methods ADD COLUMN likelihood_definitions TEXT NOT NULL DEFAULT '[]';
ALTER TABLE risk_methods ADD COLUMN impact_definitions TEXT NOT NULL DEFAULT '[]';
ALTER TABLE risks ADD COLUMN library_revision INTEGER;
-- Materialize the previously implicit method for existing default assessments.
-- Its definitions were never recorded; the newly shipped descriptions must not
-- be projected back onto those assessments.
INSERT INTO risk_methods(id,revision,scale,likelihood_labels,impact_labels,formula,matrix_json,thresholds_json,actor_name,at)
SELECT 'legacy-shipped-method',1,5,'["Rare","Unlikely","Possible","Likely","Almost certain"]','["Negligible","Minor","Moderate","Major","Severe"]','product','[]','[{"level":"Low","max":4},{"level":"Medium","max":9},{"level":"High","max":16},{"level":"Critical","max":25}]','Evidence (shipped default)',''
WHERE EXISTS(SELECT 1 FROM risk_assessments WHERE method_revision=1) AND NOT EXISTS(SELECT 1 FROM risk_methods WHERE revision=1);

-- CONNECT-001: receiving credential stays installation-local and is omitted
-- from domain archives, as provider secrets and execution grants are.
ALTER TABLE connections ADD COLUMN collector_token_hash TEXT;

-- LIFECYCLE-002 ownership handover. A reassignment is appended, never changed:
-- the departed holder, the successor, the reason and who moved it stay in the
-- item's history. The handover window is owner-set in business days.
CREATE TABLE handover_events (
 id TEXT PRIMARY KEY, person_id TEXT NOT NULL REFERENCES people(id), kind TEXT NOT NULL, item_id TEXT NOT NULL, role TEXT NOT NULL, label TEXT NOT NULL,
 to_person_id TEXT NOT NULL REFERENCES people(id), reason TEXT NOT NULL, bulk INTEGER NOT NULL DEFAULT 0 CHECK(bulk IN (0,1)), actor_id TEXT NOT NULL, actor_name TEXT NOT NULL, at TEXT NOT NULL
);
CREATE INDEX handover_events_item ON handover_events(kind,item_id,at);
CREATE TRIGGER handover_events_immutable BEFORE UPDATE ON handover_events BEGIN SELECT RAISE(ABORT,'immutable_handover'); END;
CREATE TABLE handover_settings (singleton INTEGER PRIMARY KEY CHECK(singleton=1), window_days INTEGER NOT NULL CHECK(window_days BETWEEN 1 AND 30), updated_by TEXT NOT NULL, updated_at TEXT NOT NULL);

-- VULN-002 penetration-test findings. An import keeps its report as a receipt
-- on the program's penetration-test requirement; each admitted row becomes a
-- manual finding whose SLA due date is fixed from the report date. Events and
-- retest letters are appended, never changed.
CREATE TABLE vuln_imports (
 id TEXT PRIMARY KEY, requirement_id TEXT NOT NULL, receipt_id TEXT NOT NULL, tester TEXT NOT NULL, report_date TEXT NOT NULL, report_filename TEXT NOT NULL, report_sha256 TEXT NOT NULL,
 table_filename TEXT NOT NULL, table_sha256 TEXT NOT NULL, mapping_json TEXT NOT NULL, admitted INTEGER NOT NULL, refused INTEGER NOT NULL, imported_by TEXT NOT NULL, imported_name TEXT NOT NULL, imported_at TEXT NOT NULL
);
CREATE TRIGGER vuln_imports_immutable BEFORE UPDATE ON vuln_imports BEGIN SELECT RAISE(ABORT,'immutable_vuln_import'); END;
CREATE TABLE vuln_findings (
 id TEXT PRIMARY KEY, import_id TEXT NOT NULL REFERENCES vuln_imports(id), row_number INTEGER NOT NULL, title TEXT NOT NULL, severity TEXT NOT NULL CHECK(severity IN ('critical','high','medium','low')),
 asset TEXT, resource_id TEXT, description TEXT, cve TEXT, cwe TEXT, tester TEXT NOT NULL, report_date TEXT NOT NULL, recommended_fix TEXT,
 sla_days INTEGER NOT NULL, sla_policy_id TEXT, due_date TEXT NOT NULL,
 state TEXT NOT NULL CHECK(state IN ('open','awaiting verification','closed')), marked_fixed_at TEXT, closed_at TEXT, closure_basis TEXT, closed_by TEXT
);
CREATE INDEX vuln_findings_import ON vuln_findings(import_id,row_number);
CREATE TABLE vuln_documents (
 id TEXT PRIMARY KEY, finding_id TEXT NOT NULL REFERENCES vuln_findings(id), filename TEXT NOT NULL, sha256 TEXT NOT NULL, size INTEGER NOT NULL, object_key TEXT NOT NULL UNIQUE,
 uploaded_by TEXT NOT NULL, uploaded_name TEXT NOT NULL, uploaded_at TEXT NOT NULL, decision TEXT CHECK(decision IN ('approved','rejected')), decided_by TEXT, decided_name TEXT, decided_at TEXT, decision_note TEXT
);
CREATE TABLE vuln_events (
 id TEXT PRIMARY KEY, finding_id TEXT NOT NULL REFERENCES vuln_findings(id), kind TEXT NOT NULL, body TEXT NOT NULL, document_id TEXT, actor_id TEXT NOT NULL, actor_name TEXT NOT NULL, at TEXT NOT NULL
);
CREATE INDEX vuln_events_finding ON vuln_events(finding_id,at);
CREATE TRIGGER vuln_events_immutable BEFORE UPDATE ON vuln_events BEGIN SELECT RAISE(ABORT,'immutable_vuln_event'); END;

